// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

/**
 * @title PokerTournamentToken
 * @dev ERC20 token for poker tournament funding with profit sharing
 */
contract PokerTournamentToken is ERC20, Ownable, ReentrancyGuard {

    // Tournament details
    struct TournamentInfo {
        string name;
        uint256 buyInAmount;
        uint256 totalTokens;
        uint256 tokensSold;
        uint256 profitSharePercentage; // Percentage of winnings to share (0-100)
        bool tournamentCompleted;
        uint256 totalWinnings;
        bool winningsDistributed;
    }

    TournamentInfo public tournamentInfo;

    // Mapping to track if user has claimed their share
    mapping(address => bool) public hasClaimedWinnings;

    // Events
    event TokensPurchased(address indexed buyer, uint256 amount, uint256 ethAmount);
    event TournamentCompleted(uint256 totalWinnings);
    event WinningsDistributed(address indexed recipient, uint256 amount);
    event ProfitShareUpdated(uint256 newPercentage);

    constructor(
        string memory _name,
        string memory _symbol,
        uint256 _buyInAmount,
        uint256 _totalTokens,
        uint256 _profitSharePercentage
    ) ERC20(_name, _symbol) Ownable(msg.sender) {
        require(_totalTokens > 0, "Total tokens must be greater than 0");
        require(_profitSharePercentage <= 100, "Profit share cannot exceed 100%");
        require(_buyInAmount > 0, "Buy-in amount must be greater than 0");

        tournamentInfo = TournamentInfo({
            name: _name,
            buyInAmount: _buyInAmount,
            totalTokens: _totalTokens,
            tokensSold: 0,
            profitSharePercentage: _profitSharePercentage,
            tournamentCompleted: false,
            totalWinnings: 0,
            winningsDistributed: false
        });

        // Mint all tokens to the contract
        _mint(address(this), _totalTokens);
    }

    /**
     * @dev Purchase tokens with ETH
     */
    function purchaseTokens() external payable nonReentrant {
        require(!tournamentInfo.tournamentCompleted, "Tournament already completed");
        require(tournamentInfo.tokensSold < tournamentInfo.totalTokens, "All tokens sold");
        require(msg.value > 0, "Must send ETH to purchase tokens");

        // Calculate how many tokens can be bought with the sent ETH
        uint256 tokensToBuy = (msg.value * tournamentInfo.totalTokens) / tournamentInfo.buyInAmount;

        // Ensure we don't sell more tokens than available
        uint256 availableTokens = tournamentInfo.totalTokens - tournamentInfo.tokensSold;
        if (tokensToBuy > availableTokens) {
            tokensToBuy = availableTokens;
        }

        // Calculate actual ETH cost for the tokens
        uint256 actualEthCost = (tokensToBuy * tournamentInfo.buyInAmount) / tournamentInfo.totalTokens;

        // Refund excess ETH
        if (msg.value > actualEthCost) {
            payable(msg.sender).transfer(msg.value - actualEthCost);
        }

        // Transfer tokens to buyer
        _transfer(address(this), msg.sender, tokensToBuy);
        tournamentInfo.tokensSold += tokensToBuy;

        emit TokensPurchased(msg.sender, tokensToBuy, actualEthCost);
    }

    /**
     * @dev Withdraw ETH for tournament buy-in (only owner)
     */
    function withdrawForBuyIn() external onlyOwner {
        require(!tournamentInfo.tournamentCompleted, "Tournament already completed");
        require(tournamentInfo.tokensSold > 0, "No tokens sold yet");

        uint256 balance = address(this).balance;
        require(balance > 0, "No ETH to withdraw");

        payable(owner()).transfer(balance);
    }

    /**
     * @dev Mark tournament as completed and set winnings (only owner)
     */
    function completeTournament(uint256 _totalWinnings) external onlyOwner {
        require(!tournamentInfo.tournamentCompleted, "Tournament already completed");

        tournamentInfo.tournamentCompleted = true;
        tournamentInfo.totalWinnings = _totalWinnings;

        emit TournamentCompleted(_totalWinnings);
    }

    /**
     * @dev Claim winnings based on token ownership
     */
    function claimWinnings() external nonReentrant {
        require(tournamentInfo.tournamentCompleted, "Tournament not completed yet");
        require(!hasClaimedWinnings[msg.sender], "Already claimed winnings");
        require(balanceOf(msg.sender) > 0, "No tokens to claim winnings for");

        uint256 userTokens = balanceOf(msg.sender);
        uint256 totalTokensInCirculation = tournamentInfo.tokensSold;

        // Calculate user's share of the profit
        uint256 userShare = (userTokens * tournamentInfo.totalWinnings * tournamentInfo.profitSharePercentage) / 
                           (totalTokensInCirculation * 100);

        require(userShare > 0, "No winnings to claim");
        require(address(this).balance >= userShare, "Insufficient contract balance");

        hasClaimedWinnings[msg.sender] = true;
        payable(msg.sender).transfer(userShare);

        emit WinningsDistributed(msg.sender, userShare);
    }

    /**
     * @dev Update profit share percentage (only owner, before tournament completion)
     */
    function updateProfitShare(uint256 _newPercentage) external onlyOwner {
        require(!tournamentInfo.tournamentCompleted, "Cannot update after tournament completion");
        require(_newPercentage <= 100, "Profit share cannot exceed 100%");

        tournamentInfo.profitSharePercentage = _newPercentage;
        emit ProfitShareUpdated(_newPercentage);
    }

    /**
     * @dev Get user's potential winnings
     */
    function getPotentialWinnings(address user) external view returns (uint256) {
        if (!tournamentInfo.tournamentCompleted || hasClaimedWinnings[user]) {
            return 0;
        }

        uint256 userTokens = balanceOf(user);
        if (userTokens == 0) {
            return 0;
        }

        uint256 totalTokensInCirculation = tournamentInfo.tokensSold;
        return (userTokens * tournamentInfo.totalWinnings * tournamentInfo.profitSharePercentage) / 
               (totalTokensInCirculation * 100);
    }

    /**
     * @dev Get tournament information
     */
    function getTournamentInfo() external view returns (
        string memory name,
        uint256 buyInAmount,
        uint256 totalTokens,
        uint256 tokensSold,
        uint256 profitSharePercentage,
        bool tournamentCompleted,
        uint256 totalWinnings,
        bool winningsDistributed
    ) {
        TournamentInfo memory info = tournamentInfo;
        return (
            info.name,
            info.buyInAmount,
            info.totalTokens,
            info.tokensSold,
            info.profitSharePercentage,
            info.tournamentCompleted,
            info.totalWinnings,
            info.winningsDistributed
        );
    }

    /**
     * @dev Get remaining tokens available for purchase
     */
    function getRemainingTokens() external view returns (uint256) {
        return tournamentInfo.totalTokens - tournamentInfo.tokensSold;
    }

    /**
     * @dev Get current token price in ETH
     */
    function getTokenPrice() external view returns (uint256) {
        return tournamentInfo.buyInAmount / tournamentInfo.totalTokens;
    }
}

contracts/TournamentManager.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "./PokerTournamentToken.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

/**
 * @title TournamentManager
 * @dev Factory contract to create and manage poker tournament tokens
 */
contract TournamentManager is Ownable, ReentrancyGuard {

    // Array to store all created tournament tokens
    address[] public tournaments;

    // Mapping to track tournament creators
    mapping(address => address[]) public creatorTournaments;

    // Mapping to track active tournaments
    mapping(address => bool) public isActiveTournament;

    // Events
    event TournamentCreated(
        address indexed tournamentAddress,
        address indexed creator,
        string name,
        uint256 buyInAmount,
        uint256 totalTokens,
        uint256 profitSharePercentage
    );

    event TournamentDeactivated(address indexed tournamentAddress);

    constructor() Ownable(msg.sender) {}

    /**
     * @dev Create a new poker tournament token
     */
    function createTournament(
        string memory _name,
        string memory _symbol,
        uint256 _buyInAmount,
        uint256 _totalTokens,
        uint256 _profitSharePercentage
    ) external returns (address) {
        require(_totalTokens > 0, "Total tokens must be greater than 0");
        require(_profitSharePercentage <= 100, "Profit share cannot exceed 100%");
        require(_buyInAmount > 0, "Buy-in amount must be greater than 0");
        require(bytes(_name).length > 0, "Tournament name cannot be empty");
        require(bytes(_symbol).length > 0, "Tournament symbol cannot be empty");

        // Create new tournament token
        PokerTournamentToken newTournament = new PokerTournamentToken(
            _name,
            _symbol,
            _buyInAmount,
            _totalTokens,
            _profitSharePercentage
        );

        // Transfer ownership to the creator
        newTournament.transferOwnership(msg.sender);

        address tournamentAddress = address(newTournament);

        // Add to tournaments array
        tournaments.push(tournamentAddress);

        // Track creator's tournaments
        creatorTournaments[msg.sender].push(tournamentAddress);

        // Mark as active
        isActiveTournament[tournamentAddress] = true;

        emit TournamentCreated(
            tournamentAddress,
            msg.sender,
            _name,
            _buyInAmount,
            _totalTokens,
            _profitSharePercentage
        );

        return tournamentAddress;
    }

    /**
     * @dev Get all tournaments created by a specific address
     */
    function getCreatorTournaments(address creator) external view returns (address[] memory) {
        return creatorTournaments[creator];
    }

    /**
     * @dev Get total number of tournaments
     */
    function getTotalTournaments() external view returns (uint256) {
        return tournaments.length;
    }

    /**
     * @dev Get tournament at specific index
     */
    function getTournament(uint256 index) external view returns (address) {
        require(index < tournaments.length, "Index out of bounds");
        return tournaments[index];
    }

    /**
     * @dev Get all active tournaments
     */
    function getActiveTournaments() external view returns (address[] memory) {
        uint256 activeCount = 0;

        // Count active tournaments
        for (uint256 i = 0; i < tournaments.length; i++) {
            if (isActiveTournament[tournaments[i]]) {
                activeCount++;
            }
        }

        // Create array with active tournaments
        address[] memory activeTournaments = new address[](activeCount);
        uint256 currentIndex = 0;

        for (uint256 i = 0; i < tournaments.length; i++) {
            if (isActiveTournament[tournaments[i]]) {
                activeTournaments[currentIndex] = tournaments[i];
                currentIndex++;
            }
        }

        return activeTournaments;
    }

    /**
     * @dev Deactivate a tournament (only owner or tournament creator)
     */
    function deactivateTournament(address tournamentAddress) external {
        require(isActiveTournament[tournamentAddress], "Tournament not active");

        PokerTournamentToken tournament = PokerTournamentToken(tournamentAddress);

        // Check if caller is owner of this contract or owner of the tournament
        require(
            msg.sender == owner() || msg.sender == tournament.owner(),
            "Not authorized to deactivate this tournament"
        );

        isActiveTournament[tournamentAddress] = false;

        emit TournamentDeactivated(tournamentAddress);
    }

    /**
     * @dev Get tournament details
     */
    function getTournamentDetails(address tournamentAddress) external view returns (
        string memory name,
        uint256 buyInAmount,
        uint256 totalTokens,
        uint256 tokensSold,
        uint256 profitSharePercentage,
        bool tournamentCompleted,
        uint256 totalWinnings,
        bool winningsDistributed,
        address tournamentOwner
    ) {
        PokerTournamentToken tournament = PokerTournamentToken(tournamentAddress);

        (
            name,
            buyInAmount,
            totalTokens,
            tokensSold,
            profitSharePercentage,
            tournamentCompleted,
            totalWinnings,
            winningsDistributed
        ) = tournament.getTournamentInfo();

        tournamentOwner = tournament.owner();
    }

    /**
     * @dev Emergency function to deactivate all tournaments (only owner)
     */
    function emergencyDeactivateAll() external onlyOwner {
        for (uint256 i = 0; i < tournaments.length; i++) {
            isActiveTournament[tournaments[i]] = false;
        }
    }
}

